def retry(max_versuche: int, ausnahmen: tuple = (Exception,)):
    def decorator(func: Callable):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for versuch in range(max_versuche):
                try:
                    return func(*args, **kwargs)
                except ausnahmen as e:
                    if versuch == max_versuche - 1:
                        raise
                    print(f"Versuch {versuch+1} fehlgeschlagen")
        return wrapper
    return decorator

