from typing import TypeVar, Generic, Callable, Iterator

T = TypeVar("T")
U = TypeVar("U")

class Ergebnis(Generic[T]):
    def __init__(self, wert: T, fehler: Exception = None):
        self._wert = wert
        self._fehler = fehler

    @classmethod
    def ok(cls, wert: T) -> "Ergebnis[T]":
        return cls(wert)

    @classmethod
    def fehler(cls, e: Exception) -> "Ergebnis[T]":
        return cls(None, e)

    def map(self, func: Callable[[T], U]) -> "Ergebnis[U]":
        if self._fehler:
            return Ergebnis.fehler(self._fehler)
        try:
            return Ergebnis.ok(func(self._wert))
        except Exception as e:
            return Ergebnis.fehler(e)

